def f(inp):
    cells=[(r,c) for r,row in enumerate(inp) for c,x in enumerate(row) if x==8]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0=min(rs); c0=min(cs)
    h=max(rs)-r0+1; w=max(cs)-c0+1
    pts=[[1 if inp[r][c]==8 else 0 for c in range(c0,c0+w)] for r in range(r0,r0+h)]
    n=sum(1 for row in inp for x in row if x==4)
    return [[pts[r%n][c%w]*8 for c in range(w*n)] for r in range(h)]
